-- Splynn Dimensional Market: the first 8 of the book's 19 Bio-Wizard parasites, Beastifier to Living Armor, printed 112-119.
-- 8 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~358-splynn-parasites-a.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('beastifier', 'Beastifier (Parasite)', 'rifts', 'magic', NULL, 250000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A flat disc about 6 inches (151 mm) across, usually set on the chest, with 4D6 M.D.C. It can wait up to ten years for a host and dies 1D4+6 months after joining one (its side effects instead say it drops off after 1D4+1 months, the powers staying). Any mortal host, M.D.C. D-Bees included; never supernatural beings or creatures of magic. It is only a carrier for the essence of a Boschala (Conversion Book One), anarchist or evil. Within a day P.S. turns supernatural (+6 if it already was); 4D6 days on, S.D.C. and Hit Points become M.D.C. and endurance turns supernatural (an M.D.C. D-Bee doubles its M.D.C.); a month later he bio-regenerates 4D6 M.D.C. an hour; a month later P.S. rises to 3D6+20 at most; a month after that M.D.C. rises to 1D6x100 or +200, whichever is higher; then each month brings one of nightvision 100 ft (30.5 m), see the invisible, or immunity to poison and drugs. No other bonuses. When the link is whole, 7-10 months in, the Boschala seizes control within three months and the host becomes it, his mind trapped inside until the monster dies. Surgery before the powers begin ends it harmlessly; after that only exorcism, three tries at most, which strips every power and costs 1 M.E. per two months joined. It ignores other organisms, which the finished Boschala absorbs.', 'Rifts World Book 21: Splynn Dimensional Market p.112-113', NULL),
  ('black-claw', 'Black Claw (Parasite)', 'rifts', 'magic', NULL, 100000, '100,000-150,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A 1-inch (25 mm) black, shelled, segmented worm with 12 Hit Points that lives two years without a host, mostly dormant, then stabs itself into a limb (arm, leg, tail or tentacle, never a wing) of a mortal S.D.C. host; it cannot take M.D.C. D-Bees, supernatural beings or magic creatures. After 24 hours that limb''s claws do +8 S.D.C.; 48 hours later the limb alone has supernatural P.S. and its claws add +8 M.D.; after 1D4+4 weeks it is a black Mega-Damage structure of 3D6+33 M.D.C. that regenerates 2D6 per 24 hours, is +1 to strike and parry and parries M.D. weapons unharmed. With both legs taken, kicks deal the damage, leaps go 50% farther and running is 10% faster. At three months it spawns three young and dies. At six months the limb withers: bonuses gone, and each week it loses 1D4 M.D.C. and 1 point of the +8 M.D., until it drops off, sealed and bloodless, releasing three new worms; only a mechanical bionic limb can replace it. Removal: Restoration, Purge or Psychic Purification in the first two weeks, cleanly; psychic or physical surgery or Restoration for two months after, leaving the limb''s P.S. and P.P. (and Spd for a leg) -20%; later only by losing the limb, which can take a Bio-System prosthetic until the fifth month. It attacks other organisms in its limb: -3 strike and parry and -25% to that limb''s skills for 1D4 days, lasting until one dies if the intruder has more Hit Points.', 'Rifts World Book 21: Splynn Dimensional Market p.113-114', NULL),
  ('brain-helmet', 'Brain Helmet (Parasite)', 'rifts', 'magic', NULL, 300000, '300,000-500,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A lab-cloned cousin of the Kill Crazy, shaped like a padded cyclist''s helmet over the top of the head (larger ones fit hosts up to 12 ft/3.6 m); 3D6 Hit Points, two years without a host or up to 50 bonded. Mortal hosts only. It grants Mind Block and the super-psionic Psychic Body Field for 10 I.S.P. (a 60 M.D.C. field that never grows with experience), +20+3D6 I.S.P. (a non-psychic takes that plus M.E. as base I.S.P., becomes a Minor Psychic and saves vs psionics on 12+), and +7 to save vs possession. It permanently costs 2 I.Q. and 1 M.A. and cuts P.B. by 40%; while the field is up, touch-based skills are -30% or -4 to strike. Killing it, or surgery at any time (Surgery Penalty Table for the brain, Rifts Atlantis p.114), loses the I.S.P. it gave plus 3D6 more; P.B. regains 20%, the scars and hair loss stay. A replacement gives half the I.S.P. and the full penalties again, cumulative. It lets no other organism bond to the brain: the psychic barrage kills most S.D.C. ones in 1D6 minutes; one over 10 Hit Points survives and the barrage repeats every 1D6 hours until it dies, each time leaving the host at two attacks per melee, no combat bonuses and -60% skills.', 'Rifts World Book 21: Splynn Dimensional Market p.114-115', NULL),
  ('brain-leash', 'Brain Leash (Parasite)', 'rifts', 'magic', NULL, 2000000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A slug-sized slave-control organism, lab-cloned and sterile, implanted in the brain of any host, M.D. beings included but never supernatural beings or creatures of magic; 4 Hit Points, two-year life. It takes over all voluntary movement and speech and obeys one designated being, usually the owner or taskmaster. The host stays fully aware, seeing and feeling everything, yet cannot act, even against his alignment, and does nothing without a spoken order from the controller. No bonuses. Surgery may cause brain damage: Surgery Penalty Table for the brain, Rifts Atlantis p.114. It ignores parasites and symbiotes.', 'Rifts World Book 21: Splynn Dimensional Market p.115', NULL),
  ('faceshaper', 'Faceshaper (Parasite)', 'rifts', 'magic', NULL, 100000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A half-inch (12 mm) larva set in the face of an S.D.C. host (never supernatural beings, creatures of magic or M.D.C. beings); 1D6 Hit Points each, two years as a larva and one as an adult, low animal intelligence; a mated pair breeds up to 2D4 young in its life. While the larva lives the face can be remodelled at will and holds each shape: age and flaws smoothed (+3 P.B.), a monstrous face (up to H.F. 10), or with Disguise another person''s features (+25% to the skill). Grown, it bores out through the cheek and flies away a minute later, and the face sags: P.B. -6 or halved, whichever costs more. Surgery is harmless in the first four months; after that every four months adds a cumulative -1 P.B. on removal, and killing it then costs the same; good plastic surgery or magic reconstruction restores the original P.B., otherwise it is permanent. It tolerates other organisms unless they attack the face, which it shares damage with and usually dies of.', 'Rifts World Book 21: Splynn Dimensional Market p.115-116', NULL),
  ('free-breather', 'Free Breather (Parasite)', 'rifts', 'magic', NULL, 100000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A hollow tube about a foot (0.3 m) long lining the airway from nose to lungs of a mortal host (never supernatural beings or creatures of magic); air flows through it. 4 Hit Points, two-year life; it buds one offspring every four months, which the host vomits up and which lasts a month unhosted. The host exerts himself twice as long and takes half the fatigue penalties, and his nose sharpens: recognize known scents 80%, track by scent 55%, identify poisons and toxic gases by smell 80%. But stench and gas penalties double, his saves against toxic gas, pollution and foul odors are -3, and once it dies he loses the gain and his sense of smell ends about 20% weaker than before. Surgery may do lasting harm: Surgery Penalty Table for the body, Rifts Atlantis p.114. It ignores other organisms.', 'Rifts World Book 21: Splynn Dimensional Market p.116', NULL),
  ('heavens-wings', 'Heaven''s Wings (Parasite)', 'rifts', 'magic', NULL, 500000, '500,000-1,000,000 credits, typically high for an obvious addict', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A 2-inch (50 mm) organism on the spine or base of the skull of an S.D.C. host only; 1D4 Hit Points when it bonds, 1D6+6 when it leaves grown; four-year life; after leaving it mates and the female bears up to four young. It gives magic flight without limit of time at up to 75 mph (120 km/h) and 4000 ft (1219.2 m), and in the air +4 initiative, +2 strike, +4 dodge, +4 roll with punch, +2 save vs mind control and +4 save vs Horror Factor, with a reckless euphoria. Its secretions addict: after 1D4 months the host stays aloft 16-20 hours a day. Seven numbered side effects: 1, Spd -10% per six months kept (up to four years); 2, P.E. -1 a year (the page prints RE.), and once free he regains 10% Spd and 1 P.E. per two months of hard exercise; 3, no low profile, and enemies take him for a sorcerer or superhuman; 4, after 3-4 months skills -20%; 5, after six months touchy, violent and a little paranoid under criticism; 6, after two years bonuses and flying speed halve and skills drop another -10%; 7, losing it to its 3-4 year span or to surgery brings depression: no flight or bonuses, no initiative, -1 attack per melee, combat bonuses, saves and skills halved for 1D4+2 months, then the attack returns, the combat penalties halve and skills sit at -20%. Only Restoration fully cures him. In the first six months there is a 01-65% chance he seeks another, 01-30% after six months clean, less 5% a year down to 5%; addiction takes four months, and after six months'' use a later one gives only half the bonuses, speed and high. Surgery: Surgery Penalty Table for the body, Rifts Atlantis p.114. It ignores other organisms.', 'Rifts World Book 21: Splynn Dimensional Market p.117-118', NULL),
  ('living-armor', 'Living Armor (Parasite)', 'rifts', 'magic', 20, 650000, '650,000-1,000,000 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The cheapest Bio-Wizard armor: a basketball-sized dull grey organism of 60+2D4x10 M.D.C. that spreads over 80% of a humanoid up to 12 ft (3.6 m) tall and 15% more within a year (50-65% of bulkier ones, +10% a year to 95%), and takes every hit before the host. Any mortal host, Mega-Damage beings included; never supernatural beings or creatures of magic. Lives up to 32 years, seldom past ten; anarchist animal mind that cannot be mentally controlled. Light and unhindering, other armor fits over it, about 20 lbs (9 kg) on a human; regenerates 2D6 M.D.C. a day; immune to poison, toxins, disease and ordinary heat, fire and cold. Eyes, mouth, fingers, palms, feet and groin stay bare; past 20 years it often closes over the mouth or leaves only a slit; a psychic, even a Minor one, can make it bare the face. It eats the host: in the first month half his S.D.C. and 1D6 Hit Points (10% of natural M.D.C. for a Mega-Damage being), then each year 1D4 S.D.C. and 1 Hit Point (1D4 M.D.C.), and P.E. -1 a decade; the alien look costs P.B. and M.A. -1, plus -1 per further 10 years, and a natural H.F. gains +1. When it dies it sloughs off: the host cannot act for 1D6 hours and, in combat, 01-80% flees; every loss stays and P.B. is halved for good. Killed (or removed by Restoration) within its first month it costs only a temporary loss, all but 1 point back within a week. One point of every 1D6 of magical healing goes to it (1 M.D.C. per die); psionic healing does not touch it. It tolerates other organisms and covers those on the skin.', 'Rifts World Book 21: Splynn Dimensional Market p.118-119', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 8 gear rows are in' AS assertion, count(*) AS got, 8 AS want
  FROM gear WHERE slug IN ('beastifier', 'black-claw', 'brain-helmet', 'brain-leash', 'faceshaper', 'free-breather', 'heavens-wings', 'living-armor') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~358-splynn-parasites-a.sql');
